package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;

import java.util.Arrays;
import java.util.List;

class LoanMapper {

    private static final String REASON_CODE_DELIMITER = ",";

    Loan toDomain(LoanJpaEntity entity) {
        CreditCheck creditCheck = new CreditCheck(entity.isCreditApproved(), entity.getCreditScore(),
                splitReasonCodes(entity.getCreditReasonCodes()), entity.getCreditCheckedAt(),
                entity.getCreditProviderName(), entity.getCreditProviderVersion());
        return Loan.reconstitute(entity.getId(), entity.getBookId(), entity.getMemberId(), entity.getLoanedAt(),
                entity.getDueAt(), entity.getReturnedAt(), creditCheck);
    }

    LoanJpaEntity toEntity(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(REASON_CODE_DELIMITER, creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    private static List<String> splitReasonCodes(String reasonCodes) {
        if (reasonCodes == null || reasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(reasonCodes.split(REASON_CODE_DELIMITER));
    }
}

