    public GetLoanService(LoadLoanPort loadLoanPort) {
        this.loadLoanPort = loadLoanPort;
    }

    @Override
    public Loan getLoan(UUID loanId) {
        return loadLoanPort.loadLoan(loanId).orElseThrow(() -> new LoanNotFoundException(loanId));
    }
